import {musicIntentView,musicIntentFor} from './music.js';
import { matchesEditorialReview, editorialReviewFilter, esc, human, date, safeUrl, storyUrl, effective, workingStory, mediaFor, badge, stateLabel, nextAction, image, empty, external, sectionHeading, storyCard, blockers, draftNotice, fieldDisabled, proposalControl } from './components.js';
import { directionView, creativeBriefSummary } from './direction.js';

const allStories = state => (state.workspace?.stories || []).map(workingStory);
const filtered = (stories, query) => !query ? stories : stories.filter(s => `${s.title} ${s.subject} ${s.hook} ${s.id}`.toLowerCase().includes(query.toLowerCase()));
const count = (stories, group) => stories.filter(story => stateLabel(story).group === group).length;
const tabs = [['overview', 'Overview'], ['direction', 'Direction'], ['research', 'Research'], ['images', 'Images'], ['carousel', 'Carousel'], ['caption', 'Caption'], ['music', 'Music'], ['publishing', 'Publishing']];
const aggregationLabel = value => ({ mean_of_observed_post_rates: 'Average of measured post rates', sum_of_observed_post_values: 'Total across measured posts' })[value] || 'Reported measurement';

function pageHeader(kicker, title, description, action = '') {
  return `<div class="page-heading"><div><p class="eyebrow">${esc(kicker)}</p><h1>${esc(title)}</h1><p class="page-description">${esc(description)}</p></div>${action}</div>`;
}

export {home} from './today.js';

function existingSourceNotes(story) {
  const notes = [['Founder notes', story.sourceNotes], ['Production direction', story.productionNotes], ['Source review notes', story.sourceReviewNotes]].filter(([, value]) => typeof value === 'string' && value.trim());
  return notes.length ? `<section class="editorial-panel existing-source-notes"><div class="section-heading"><div><h2>Source notes</h2><p>Earlier editorial direction, retained with the original story.</p></div></div>${notes.map(([label, value]) => `<details><summary>${label}</summary><p>${esc(value)}</p></details>`).join('')}</section>` : '';
}

export function pipeline(state) {
  const stories = filtered(allStories(state), state.search);
  const groups = [['all', 'All stories'], ['research', 'Research'], ['production', 'In production'], ['publishing', 'Publishing'], ['archive', 'Reported published']];
  const visible = state.pipelineGroup === 'all' ? stories : stories.filter(s => stateLabel(s).group === state.pipelineGroup);
  return `${pageHeader('Your stories', 'Stories', 'Saved ideas, working drafts and existing editorial work.')}
    <div class="filter-bar"><div class="filter-chips" aria-label="Filter stories by stage">${groups.map(([key, label]) => `<button class="filter-chip ${state.pipelineGroup === key ? 'active' : ''}" data-action="pipeline-filter" data-value="${key}" aria-pressed="${state.pipelineGroup === key}">${label}<span>${key === 'all' ? stories.length : count(stories, key)}</span></button>`).join('')}</div><span class="small muted">${visible.length} ${visible.length === 1 ? 'story' : 'stories'}</span></div>
    <div class="pipeline-list">${visible.length ? visible.map((story, index) => { const status = stateLabel(story); const action = nextAction(story); return `<article class="pipeline-row"><span class="row-number">${String(index + 1).padStart(2, '0')}</span><a class="pipeline-thumb" href="${storyUrl(story.id)}" aria-label="Open ${esc(story.title)}">${image(mediaFor(story)[0] || story.media?.[0])}</a><div class="pipeline-title"><p class="eyebrow">${esc(story.subject || story.format)}</p><h2><a href="${storyUrl(story.id)}">${esc(story.title)}</a></h2><small>${esc(story.id)}${story.localDraft ? ' · draft saved' : ''}</small></div><div class="pipeline-status">${badge(status.label, status.tone)}<span>${effective(story).selectedAssetIds.length} / ${story.targetSlideCount || '—'} slides selected</span><span>${(story.blockers || []).length} checks to review</span></div><a class="row-action" href="${storyUrl(story.id, action.tab)}">${esc(action.label)} <span aria-hidden="true">→</span></a></article>`; }).join('') : empty('No stories in this view', 'Try another editorial stage or clear the search.')}</div>`;
}

export function editorialAuditNotice(story) {
  return story.editorialAudit?.issues.length?`<section class="notice warning"><strong>Editorial checks need attention</strong><ul>${story.editorialAudit.issues.map(i=>`<li>${esc(i.message)}</li>`).join('')}</ul><p class="small muted">Text and metadata checks only. No automatic taste or pixel analysis.</p></section>`:'';
}

const storyStages = [
  {label:'Understand',tab:'overview',tabs:[['overview','Story'],['research','Research & sources']]},
  {label:'Images',tab:'images',tabs:[['images','Photographs']]},
  {label:'Angle',tab:'direction',tabs:[['direction','Creative direction']]},
  {label:'Edit',tab:'caption',tabs:[['caption','Caption'],['carousel','Carousel'],['music','Music']]},
  {label:'Check',tab:'publishing',tabs:[['publishing','Before publishing']]},
];
export function storyWorkspace(state, story, tab) {
  story = workingStory(story);
  const content = { overview: storyOverview, direction: directionView, research: storyResearch, images: storyImages, carousel: storyCarousel, caption: storyCaption, music: storyMusic, publishing: storyPublishing };
  if (!content[tab]) tab = 'overview';
  const status = stateLabel(story),stage=storyStages.find(item=>item.tabs.some(([id])=>id===tab));
  return `<a class="back-link" href="#/stories">← All stories</a><div class="story-heading"><div><p class="eyebrow">${esc(story.subject || 'Editorial story')}</p><h1>${esc(story.title)}</h1><div class="story-meta">${badge(status.label, status.tone)}<span>${esc(human(story.format))}</span></div></div></div>
    ${draftNotice(story)}<nav class="story-stages" aria-label="Story stages">${storyStages.map((item,index)=>`<a href="${storyUrl(story.id,item.tab)}" ${item===stage?'aria-current="step"':''}><small aria-hidden="true">${String(index+1).padStart(2,'0')}</small>${item.label}</a>`).join('')}</nav>
    <nav class="story-stage-tools story-tabs" aria-label="Story workspace">${stage.tabs.map(([id,label])=>`<a href="${storyUrl(story.id,id)}" ${id===tab?'aria-current="page"':''}>${label}${id==='images'?`<small>${story.media?.length||0}</small>`:''}</a>`).join('')}</nav>
    <details class="story-record-details system-details"><summary>Story details & version history</summary><p class="small muted">Story <code>${esc(story.id)}</code> · ${story.packageVersion?`Production package v${esc(story.packageVersion)}`:'No production package recorded'}. Changes save privately; production records remain separate.</p>${story.origin==='n8n_development'?`<p class="small"><strong>Research proposal</strong> · Execution ${esc(story.engineProvenance?.executionId||'not recorded')}.${story.discoveryPlan?` ${esc(human(story.discoveryPlan.approach))} · ${esc(human(story.discoveryPlan.territory))} · preset ${esc(human(story.discoveryPlan.preset))}.`:''} ${story.generationFormatBasis==='provisional_single_frame_before_drafting'?'Held before drafting; the single-frame placeholder is not a generated format decision. ':''}This is not a production-table record, source verification or publication approval.</p>`:''}<div class="story-header-actions">${proposalControl(story,'Download working copy ↗')}<button class="text-button" data-action="draft-history" data-story="${esc(story.id)}">Version history</button></div></details>
    <div data-editorial-audit>${editorialAuditNotice(story)}</div><div class="story-workspace">${content[tab](state, story)}</div>`;
}

export function readinessPanel(story){
 const assessment=story.readiness;if(!assessment)return '';
 return `<section class="editorial-panel"><h2>Before publishing</h2><p>${esc(human(assessment.status))}. Checks separate source evidence from editorial judgment and publication clearance.</p><ul class="editorial-checks">${assessment.checks.map(check=>`<li>${badge(human(check.status),check.status==='needs_research'?'warn':'quiet')}<div><a class="text-link" href="${storyUrl(story.id,check.tab)}">${esc(check.label)} →</a><p>${esc(check.detail)}</p></div></li>`).join('')}</ul></section>`;
}

function storyDecision(story){
 if(story.origin!=='n8n_development'||!Number.isInteger(story.engineReviewVersion))return '';
 const decision=story.developmentDecision;
 return `<section class="editorial-panel"><h2>Editorial decision</h2><p>Keep the decision with this story. It is saved in the existing development job history; original research and working revisions remain intact.</p>${decision?`<p><strong>${esc(human(decision.decision))}</strong> · ${esc(human(decision.reviewer||'editor'))} · ${esc(human(decision.basis||'general'))}: ${esc(decision.reason)}</p>`:''}<form data-engine-review data-request="${esc(story.engineJobId)}" data-candidate="${esc(story.engineCandidateId)}" data-version="${story.engineReviewVersion}"><label class="field-label">Editorial decision<select name="decision" aria-label="Development editorial decision">${[['needs_research','Needs further research'],['approved','Ready for editorial development'],['rejected','Pass on this angle']].map(([value,label])=>`<option value="${value}" ${decision?.decision===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="field-label">Decision basis<select name="basis" aria-label="Decision basis">${[['editorial_taste','Editorial taste'],['source_accuracy','Source accuracy'],['visual_relevance','Visual relevance'],['rights','Rights'],['general','General review']].map(([value,label])=>`<option value="${value}" ${(decision?.basis||'editorial_taste')===value?'selected':''}>${label}</option>`).join('')}</select></label><label class="field-label">Decision reason<textarea name="reason" minlength="10" maxlength="2000" required>${esc(decision?.reason||'')}</textarea></label><button class="small-button" type="submit">Save editorial decision</button><p data-engine-status role="status"></p></form><p class="small muted">This decision does not verify facts, clear rights, export media or approve publishing.</p></section>`;
}

function storyOverview(state, story) {
  const selected = mediaFor(story),photographs=selected.length?selected:(story.media||[]).slice(0,3);
  const action = nextAction(story);
  return `<div class="workspace-main"><section class="story-premise editorial-panel"><p class="eyebrow">The story</p><h2 class="serif-heading">${esc(story.hook || story.title)}</h2><p class="small muted">${selected.length?`${selected.length} selected photographs`:`${story.media?.length||0} photographic references to explore`} · ${(story.research||[]).length} recorded source claims</p></section>
    <section class="story-contact-sheet">${sectionHeading(selected.length?'Your selected photographs':'A first look', selected.length?'In your saved order.':'References from this story; inspect their original context.',`<a class="text-link" href="${storyUrl(story.id,'images')}">Review images →</a>`)}${photographs.length?`<div class="contact-strip">${photographs.slice(0,6).map((asset,index)=>image(asset,{index,storyId:story.id})).join('')}</div>`:empty('Find the opening photograph','No image references are attached to this story yet.',`<a class="text-link" href="${storyUrl(story.id,'research')}">Review the research →</a>`)}</section>
    <section class="editorial-panel"><div class="section-heading"><div><h2>Editor’s working notes</h2><p>Your angle, questions and image decisions. Saved privately.</p></div><button class="text-button" data-action="notes-template" data-story="${esc(story.id)}" ${fieldDisabled(story)}>Add research checklist</button></div><label class="sr-only" for="editor-notes">Editor’s working notes</label><textarea id="editor-notes" data-draft-field="notes" data-story="${esc(story.id)}" rows="5" placeholder="The strongest angle, unresolved questions, image decisions…" ${fieldDisabled(story)}>${esc(effective(story).notes)}</textarea></section>
    <details class="editorial-panel"><summary>Caption in progress</summary><p class="body-copy">${esc(effective(story).caption || 'No caption saved yet.')}</p><a class="text-link" href="${storyUrl(story.id,'caption')}">Edit the caption →</a></details>${existingSourceNotes(story)}${story.origin==='n8n_development'?`<details class="editorial-panel"><summary>Earlier editorial assessment</summary>${storyDecision(story)}</details>`:''}</div>
    <aside class="workspace-aside"><section class="next-action"><p class="eyebrow">Next for this story</p><h2>${esc(action.label)}</h2><p>${esc(action.reason)}</p><a class="button button-dark" href="${storyUrl(story.id,action.tab)}">Continue →</a></section><details class="aside-block"><summary>Before publishing</summary>${blockers(story)}<div data-readiness-panel>${readinessPanel(story)}</div><a class="text-link" href="${storyUrl(story.id,'publishing')}">Finish required checks →</a></details></aside>`;
}

function selectionReviewPanel(story){
 const result=story.editorialSelection;const founder=story.developmentDecision?.reviewer==='founder'&&story.developmentDecision.basis==='editorial_taste';
 if(!result&&!founder)return '';
 const ec=story.editorialCase||{};
 return `<section class="editorial-panel"><h2>Editorial selection reasoning</h2>${founder?`<p><strong>Founder taste decision: ${esc(human(story.developmentDecision.decision))}</strong></p><p>${esc(story.developmentDecision.reason)}</p><p class="small muted">Publication fit, separate from factual correctness and objective photographic attractiveness.</p>`:''}${result?`<p>${badge(human(result.decision),result.decision==='advance'?'quiet':'warn')} · ${esc(human(result.basis))}</p><ul>${[...result.reasons,...(result.rationale||[])].map(r=>`<li>${esc(r.message)}</li>`).join('')}</ul><dl>${[['recommendation','Research recommendation'],['comparison_reason','Comparison reasoning'],['cultural_payoff','Cultural payoff'],['visual_detail','Proposed visual detail'],['image_story_connection','Image/story connection'],['preset_connection','Preset connection'],['familiarity_risk','Familiarity check'],['format_potential','Format potential'],['research_uncertainty','Research uncertainty'],['visual_evidence_basis','Visual evidence basis']].map(([key,label])=>ec[key]?`<dt>${label}</dt><dd>${esc(ec[key])}</dd>`:'').join('')}</dl><p class="small muted">A source-led editorial proposal, not verified aesthetic quality or pixel inspection.</p>`:''}${story.leadComparison?.length?`<details><summary>Research leads compared · ${story.leadComparison.length}</summary><p class="small muted">Bounded leads from one research response, not additional generated stories or independently verified alternatives. Prepared territory: ${esc(story.selectionProvenance?.preparedTerritory)}; selected candidate territory: ${esc(story.selectionProvenance?.candidateTerritory)}.</p><ul>${story.leadComparison.map(c=>`<li><strong>${esc(c.subject)}</strong> · ${esc(c.decision)}${c.selected?' · selected':''}<p>${c.reasons.map(r=>esc(r.message)).join(' ')}</p>${c.hook?`<p>${esc(c.hook)}</p>`:''}${c.editorialCase?.comparison_reason?`<p>${esc(c.editorialCase.comparison_reason)}</p>`:''}${c.visual?.reference_url?`<p><a href="${esc(c.visual.reference_url)}" target="_blank" rel="noreferrer">Image source to inspect</a> · photographic quality and rights unverified</p>`:''}${c.claims?.length?`<details><summary>Retained research references · ${c.claims.length}</summary><ul>${c.claims.map(claim=>`<li>${esc(claim.claim)} ${claim.source_url?`<a href="${esc(claim.source_url)}" target="_blank" rel="noreferrer">Source</a>`:' · reference unavailable'}</li>`).join('')}</ul><p class="small muted">Research proposals; source access and photographic quality remain unverified.</p></details>`:''}</li>`).join('')}</ul></details>`:''}</section>`;
}

function storyResearch(state, story) {
  const claims = story.research || [];
  const sourceIssues = story.intelligence?.sourceIssues || [];
  return `<div class="workspace-main">${selectionReviewPanel(story)}${sectionHeading('A story built on sources', 'Recorded claims and citations from the existing dossier. Source labels are not new verification.')}${claims.length ? `<div class="research-list">${claims.map((claim, i) => `<article class="research-claim"><span class="claim-number">${String(i + 1).padStart(2, '0')}</span><div><p>${esc(claim.claim)}</p><div class="research-meta">${badge(claim.claimType === 'verified_fact' ? (story.origin==='n8n_development'?'Model-labeled fact':'Recorded as fact') : human(claim.claimType))}${external(claim.url, claim.sourceName || 'Original source')}${claim.capturedAccess?badge(human(claim.capturedAccess),claim.capturedAccess==='source_text_captured'?'quiet':'warn'):''}</div>${claim.capturedAccess==='source_text_captured'&&claim.capturedTextExcerpt?`<details class="captured-source-excerpt"><summary>Read the recorded source excerpt</summary><p class="small muted">${esc(claim.capturedSourceTitle||claim.sourceName)}${claim.capturedHttpStatus?' · HTTP '+claim.capturedHttpStatus:''}. Extracted source text; verify its support for the exact claim.</p><blockquote class="body-copy">${esc(claim.capturedTextExcerpt)}</blockquote></details>`:''}</div></article>`).join('')}</div>` : empty('The dossier needs evidence', 'No structured source claims are attached to this story. The existing Founder Studio remains available for source-led research.')}
    ${existingSourceNotes(story)}${sourceIssues.length ? `<section class="notice warning"><h3>Source review</h3><ul>${sourceIssues.map(issue => `<li>${esc(issue.message || human(issue.code || issue))}</li>`).join('')}</ul></section>` : ''}
    <section class="editorial-panel"><h2>Research notes</h2><p class="muted">Separate evidence from interpretation. These notes stay in your private working copy.</p><label class="sr-only" for="research-notes">Research notes</label><textarea id="research-notes" data-draft-field="notes" data-story="${esc(story.id)}" rows="9" ${fieldDisabled(story)}>${esc(effective(story).notes)}</textarea></section></div><aside class="workspace-aside"><section class="aside-block"><p class="eyebrow">Fact-checking boundary</p><h3>Keep the evidence visible.</h3><p>This workspace displays the dossier’s stored claims and source links. It has not independently revisited source pages or verified their claims.</p><p>Record the original passage, date and creator before moving a claim into the final caption.</p></section><section class="aside-block"><h3>Current review state</h3>${badge(story.sourceClaimsReviewed ? 'Source review recorded' : 'Source review not complete', story.sourceClaimsReviewed ? 'good' : 'warn')}<p>Recorded review does not clear image reproduction rights.</p></section></aside>`;
}

function assetCard(story, asset, selected, compared = false) {
  return `<article class="asset-card ${selected ? 'selected' : ''}">${image(asset, { storyId: story.id })}<div class="asset-copy"><p class="eyebrow">${esc(asset.creator || asset.provider || 'Creator unrecorded')}</p><h3><button class="title-button" data-action="inspect" data-story="${esc(story.id)}" data-asset="${esc(asset.id)}">${esc(asset.title || 'Untitled source image')}</button></h3><div class="asset-meta">${asset.localReview?badge(`Your ${human(asset.localReview.decision)}`,asset.localReview.decision==='reject'?'warn':'quiet'):''}${badge(asset.rightsStatus === 'cleared' ? 'Clearance recorded' : 'Rights pending', asset.rightsStatus === 'cleared' ? 'good' : 'warn')}<span>${asset.width && asset.height ? `${esc(asset.width)} × ${esc(asset.height)}` : 'Dimensions not recorded'}</span></div><div class="asset-actions"><button class="small-button ${selected ? 'is-selected' : ''}" data-action="toggle-asset" data-story="${esc(story.id)}" data-asset="${esc(asset.id)}" aria-pressed="${selected}" ${fieldDisabled(story)}>${selected ? '✓ In your sequence' : '+ Add to sequence'}</button><button class="text-button" data-action="compare-asset" data-story="${esc(story.id)}" data-asset="${esc(asset.id)}" aria-pressed="${compared}">${compared ? '✓ Compare' : 'Compare'}</button></div></div></article>`;
}

function storyImages(state, story) {
  const selected = effective(story).selectedAssetIds;
  const candidates = (story.media || []).filter(asset=>matchesEditorialReview(asset,state.imageEditorialFilter||'all'));
  return `<div class="workspace-full">${sectionHeading('Choose the photographs', 'Build the sequence. Image permissions remain a separate review.', `<a class="button button-light" href="${storyUrl(story.id, 'carousel')}">Review ${selected.length} slides →</a>`)}<p class="small muted">Open a photograph for its creator, original source and permission details. Previews may be restricted.</p><div class="library-tools">${editorialReviewFilter(state.imageEditorialFilter||'all')}<span class="small muted">${candidates.length} of ${story.media.length} candidates</span></div><details><summary>Possible image variants · ${story.visualVariants?.length||0}</summary><p>Advisory pixel-hash resemblance only. Distinct frames stay separate; compare full images before deciding. No identity, rights or aesthetic finding.</p><ul>${(story.visualVariants||[]).map(v=>`<li>${v.assetIds.map(id=>esc(story.media.find(m=>m.id===id)?.title||id)).join(" ↔ ")}</li>`).join("")}</ul></details><div class="asset-grid">${candidates.length ? candidates.map(asset => assetCard(story, asset, selected.includes(asset.id), state.compared.some(c => c.storyId === story.id && c.assetId === asset.id))).join('') : empty('No candidates in this editorial view', 'Change the editorial filter to see other recorded candidates, or continue sourcing in the existing Founder Studio.')}</div></div>`;
}

function sourceSequenceOptions(story) {
  const plan=story.sourceSequencePlan;
  if(!plan?.options.length)return '';
  return `<section class="editorial-panel">${sectionHeading('An evidence-led starting point', 'Choose a proposal after reviewing the original frames. Source captions establish context; they do not judge the pixels or grant rights.')}<div class="source-sequence-options">${plan.options.map((option,index)=>`<details><summary>${esc(option.label)} · ${option.targetSlideCount} ${option.targetSlideCount===1?'frame':'frames'}</summary><ol class="source-sequence-slides">${option.slides.map(slide=>{const asset=story.media.find(m=>m.id===slide.assetId);return `<li>${image(asset,{storyId:story.id})}<div><p class="eyebrow">${esc(human(slide.material))}${slide.years.length?' · '+slide.years.join(', '):' · date not recorded'}</p><p>${esc(slide.caption)}</p><p class="small muted">${esc(slide.credit)}</p></div></li>`;}).join('')}</ol><p class="small muted">Different dates remain explicit. Costume documents are not film stills. This replaces the working selection and frame target; earlier versions stay in history.</p><button class="small-button" data-action="apply-source-sequence" data-story="${esc(story.id)}" data-index="${index}" ${fieldDisabled(story)}>Use ${option.targetSlideCount}-frame source plan</button></details>`).join('')}</div></section>`;
}

function storyCarousel(state, story) {
  const selected = mediaFor(story);
  const current = effective(story);
  const target = story.targetSlideCount || null;
  return `<div class="workspace-main">${sectionHeading('Build the visual sequence', 'Drag slides or use the move controls. Your image order saves privately.', `<div class="carousel-actions"><button class="small-button" data-action="rehearse-story" data-story="${esc(story.id)}" ${selected.length ? '' : 'disabled'}>Rehearse carousel</button><a class="text-link" href="${storyUrl(story.id, 'images')}">Add photographs →</a></div>`)}${selected.length ? `<ol class="carousel-list" aria-label="Ordered carousel slides">${selected.map((asset, index) => `<li class="carousel-slide" draggable="${!story.localDraft?.stale}" data-slide-index="${index}" data-story="${esc(story.id)}"><span class="drag-handle" aria-hidden="true">⠿</span>${image(asset, { index, storyId: story.id })}<div class="slide-copy"><p class="eyebrow">${index === 0 ? 'Opening image' : `Slide ${index + 1}`}</p><h3>${esc(asset.title || 'Untitled image')}</h3><p>${esc(asset.creator || 'Creator unrecorded')}</p>${badge(asset.rightsStatus === 'cleared' ? 'Clearance recorded' : 'Rights pending', asset.rightsStatus === 'cleared' ? 'good' : 'warn')}</div><div class="slide-controls"><button class="icon-button" data-action="move-slide" data-story="${esc(story.id)}" data-index="${index}" data-direction="-1" aria-label="Move slide ${index + 1} earlier" ${index === 0 || story.localDraft?.stale ? 'disabled' : ''}>↑</button><button class="icon-button" data-action="move-slide" data-story="${esc(story.id)}" data-index="${index}" data-direction="1" aria-label="Move slide ${index + 1} later" ${index === selected.length - 1 || story.localDraft?.stale ? 'disabled' : ''}>↓</button><button class="icon-button remove-slide" data-action="toggle-asset" data-story="${esc(story.id)}" data-asset="${esc(asset.id)}" aria-label="Remove slide ${index + 1} from local sequence" ${fieldDisabled(story)}>×</button></div></li>`).join('')}</ol>` : empty('Start with the opening photograph', 'Choose a candidate from the story’s existing image library, then shape the narrative one slide at a time.', `<a class="button button-dark" href="${storyUrl(story.id, 'images')}">Choose images →</a>`)}
    ${sourceSequenceOptions(story)}<section class="editorial-panel"><h2>The caption beside the sequence</h2><p class="body-copy">${esc(current.caption || 'No caption has been saved.')}</p><a class="text-link" href="${storyUrl(story.id, 'caption')}">Edit the caption →</a></section></div><aside class="workspace-aside"><section class="aside-block"><p class="eyebrow">Carousel review</p><h3>${selected.length}${target ? ` / ${target}` : ''} slides selected</h3><ul class="check-list"><li>${selected.length ? '✓' : '○'} At least one photograph</li><li>${!target || selected.length === target ? '✓' : '○'} ${target ? `${story.localDraft?.targetSlideCount ? 'Working target' : 'Source target'}: ${target} slides` : 'No source slide target recorded'}</li><li>${selected.every(a => a.width === 1080 && a.height === 1350) && selected.length ? '✓' : '○'} 1080 × 1350 dimensions recorded</li><li>${selected.every(a => a.rightsStatus === 'cleared') && selected.length ? '✓' : '○'} Per-image clearance recorded</li></ul><p class="small muted">These are record checks, not a decoded JPG/export verification. Local proposals do not generate or upload files.</p></section><section class="aside-block"><h3>Ready for a considered review.</h3><p>Use the existing n8n export flow after approving the selection. Download your working copy for review.</p>${proposalControl(story, 'Download proposal ↗')}</section></aside>`;
}

function storyCaption(state, story) {
  const caption = effective(story).caption;
  return `<div class="workspace-main">${sectionHeading('Make every word earn its place.', 'Shape your working caption. The original source caption stays available below.')}<label class="field-label" for="caption-editor">Caption draft</label><textarea class="caption-editor" id="caption-editor" aria-label="Local caption draft" data-draft-field="caption" data-story="${esc(story.id)}" rows="13" ${fieldDisabled(story)}>${esc(caption)}</textarea><div class="caption-toolbar"><span data-caption-count class="${[...caption].length > 2200 ? 'error-text' : ''}">${[...caption].length} / 2,200 characters</span><span>${state.workspace.hosted?'Autosaves to your private Studio':'Autosaves locally'}</span></div><p data-caption-warning class="inline-warning" ${[...caption].length <= 2200 && !/INTERNAL[\s\S]{0,60}TEST|DO\s+NOT\s+PUBLISH/iu.test(caption) ? 'hidden' : ''}>Review caption length or internal-test markers before any handoff.</p>
    <div data-caption-checks>${captionChecks(story)}</div><details class="source-caption"><summary>Compare with the saved source caption</summary><p class="body-copy">${esc(story.caption || 'No source caption recorded.')}</p></details></div><aside class="workspace-aside"><section class="aside-block"><h3>The editorial pass</h3><ol class="numbered-notes"><li>Lead with the specific, unusual fact.</li><li>Keep the photographer and historical context visible.</li><li>Remove instructions to the production team.</li><li>Check each factual claim against its original source.</li><li>Preserve credits and permission requirements.</li></ol></section><section class="aside-block"><h3>Keep sources close.</h3><p>${(story.research || []).length} recorded source claims are attached to this story.</p><a class="text-link" href="${storyUrl(story.id, 'research')}">Review research →</a></section></aside>`;
}

export function captionChecks(story) {
  const issues = story.intelligence?.caption?.issues || [];
  return `<section class="editorial-panel"><h2>Editorial checks</h2>${issues.length ? `<ul class="editorial-checks">${issues.map(issue => `<li>${badge(human(issue.severity || 'review'), issue.severity === 'error' ? 'warn' : '')}<span>${esc(issue.message || human(issue.code))}</span></li>`).join('')}</ul>` : '<p class="muted small">No additional text-check flags were supplied for the last saved context.</p>'}<p class="small muted">Checks reflect the last saved local or source context. They support editorial judgment and do not fact-check the caption.</p></section>`;
}

function storyMusic(state, story) {
  const selection = effective(story).musicSelection;
  const recommendations = story.musicRecommendations || story.intelligence?.musicRecommendations || [];
  const intent=musicIntentFor(story);
  return `<div class="workspace-main">${sectionHeading('Find the story’s sound.', 'Recommendations use editorial text and metadata. No audio or image-pixel analysis is implied.')}<section class="selected-track"><span class="record-icon" aria-hidden="true">◎</span><div><p class="eyebrow">${story.localDraft?.musicSelection ? 'Working sound direction' : 'Saved sound direction'}</p><h2>${esc(selection?.track || (intent.mode==='silent'?'A silent post':'No track selected'))}</h2><p>${esc(selection?.artist || 'Choose a recommendation or record a direction below.')}</p></div>${selection?`<button class="small-button" data-action="clear-track" data-story="${esc(story.id)}" ${fieldDisabled(story)}>Clear track selection</button>`:''}</section>${musicIntentView(state,story)}<div class="track-list">${recommendations.length ? recommendations.map((track, index) => `<article class="track"><span class="track-index">${String(index + 1).padStart(2, '0')}</span><div><h3>${esc(track.track || track.title)}</h3><p>${esc(track.artist)}</p><small>${esc(track.reason || track.reasons?.join('; ') || 'Suggested from this story’s editorial metadata.')}</small>${track.briefWarnings?.length?`<p class="inline-warning">${esc(track.briefWarnings.join(' '))}</p>`:''}${track.catalogNote?`<details><summary>Catalog note · not an audition</summary><p class="small">${esc(track.catalogNote)}</p></details>`:''}<p class="small">${external('https://open.spotify.com/search/'+encodeURIComponent((track.artist||'')+' '+(track.track||track.title||'')), 'Find a recording ↗')}</p></div><button class="small-button" data-action="choose-track" data-story="${esc(story.id)}" data-index="${index}" ${fieldDisabled(story)}>${selection?.track === track.track && selection?.artist === track.artist ? '✓ Selected' : 'Use this track'}</button></article>`).join('') : empty('No recommendations supplied', 'The existing source catalog has not returned a ranked selection for this story.')}</div><section class="editorial-panel"><h2>Record another direction</h2><p class="muted">A saved editorial preference. Check availability in Instagram before publishing.</p><form data-form="music" data-story="${esc(story.id)}"><div class="field-pair"><label>Track<input name="track" maxlength="200" required value="${esc(selection?.track || '')}" ${fieldDisabled(story)}></label><label>Artist<input name="artist" maxlength="200" required value="${esc(selection?.artist || '')}" ${fieldDisabled(story)}></label></div><button class="button button-dark" type="submit" ${fieldDisabled(story)}>Save sound direction</button></form></section></div><aside class="workspace-aside"><section class="aside-block"><h3>Check it in Instagram.</h3><p>Music availability and usage rights can vary by account, region and purpose. Confirm the actual track inside Instagram before publication.</p><p>No playback or music licensing is provided by this workspace.</p></section></aside>`;
}

function nativeDecisions(story){return `<section class="editorial-panel"><h2>Your next editorial decisions</h2>${(story.productionDecisions||[]).map(d=>`<article><h3><a href="${storyUrl(story.id,d.tab)}">${esc(d.title)} →</a></h3><p>${esc(d.detail)}</p>${d.evidence?.length?`<details><summary>Recorded references · ${d.evidence.length}</summary><ul>${d.evidence.map(e=>`<li>${esc(e.creator||e.claim||e.postId||e.assetId)}${e.status?' · '+esc(human(e.status)):''}${e.url?' · '+external(e.url,'Source to review'):''}</li>`).join('')}</ul></details>`:''}</article>`).join('')||'<p>No additional editorial decision was identified in this snapshot. Native preflight remains required.</p>'}</section>`;}

export function productionVisibility(story){
 const p=story.production||{},pkg=p.package,prep=story.productionPreparation;
 return `<section class="editorial-panel"><h2>Existing production package</h2><p class="small muted">n8n observation: ${esc(date(p.observedAt))} ET · Buffer observation: ${esc(date(p.providerObservedAt))} ET. These are timestamped snapshots, not a fresh Instagram availability check.</p>${pkg?`<dl><dt>Package identity</dt><dd><code>${esc(pkg.id||'ID missing')}</code> · version ${esc(pkg.version||'unknown')}</dd><dt>Editorial handoff</dt><dd>Version ${esc(pkg.editorialHandoffVersion||'not recorded')}</dd><dt>Final approval</dt><dd>${esc(human(pkg.finalApprovalStatus))}</dd><dt>Claims review</dt><dd>${pkg.sourceClaimsReviewed?'Recorded in native package':'Not recorded'} · ${esc(pkg.sourceReviewNotes)}</dd><dt>Rights review</dt><dd>${esc(human(pkg.rightsStatus))}; per-image permission evidence still applies</dd><dt>Render preflight</dt><dd>${esc(human(pkg.renderPreflightStatus||'unknown'))}</dd></dl>`:`<p>${p.relationship==='ambiguous'?'Multiple native package rows exist. Resolve their identity before preparing a release.':'No authoritative production package is linked. A development story remains separate until accepted through the existing n8n process.'}</p>`}
 <details><summary>Existing exports and proofs</summary>${!p.proofs?.length?'<p>No proof is linked by an explicit package execution reference. Unmapped proofs are not assigned by title.</p>':''}<ul>${(p.exports||[]).map(e=>`<li>${esc(e.filename||e.id)} · v${esc(e.version||'unknown')} · ${e.current?'current recorded package version':'historical or unresolved version'} · ${esc(human(e.status))}</li>`).join('')}${(p.archives||[]).map(e=>`<li>${external(e.url,e.filename||e.id)} · ${e.current?'exact package/version reference':'historical or unresolved reference'} · ${e.verifiedPrivate?'private archive verification recorded':'archive verification unresolved'}</li>`).join('')}${(p.proofs||[]).map(e=>`<li>${external(e.url,e.label||e.id)} · recorded package execution reference; proof version unverified</li>`).join('')}</ul>${!p.coverage?.exports||!p.coverage?.proofs?'<p>Some export/proof tables were not available in this snapshot. Absence is unverified.</p>':''}</details>
 <details><summary>Recorded handoff history · ${p.handoffs?.length||0}</summary><ul>${(p.handoffs||[]).map(h=>`<li>${esc(human(h.path))} · v${esc(h.packageVersion||'unknown')} · ${esc(human(h.state))} · ${esc(date(h.at))} ET · <code>${esc(h.postId||'provider ID missing')}</code></li>`).join('')}</ul><p>Historical draft creation records describe the transfer then. Current provider status appears separately below; a sent record is not proof Instagram is still live.</p></details>
 <ul>${(p.provider||[]).map(post=>`<li><code>${esc(post.id)}</code> · ${esc(human(post.status))} · observed ${esc(date(post.observedAt))} ET${post.url?` · ${external(post.url,'Reported provider link')}`:''}</li>`).join('')}</ul>
 ${prep?`<h3>Next production action</h3><p>${esc(prep.nextAction)}</p><ul>${prep.blockers.map(b=>`<li>${esc(human(b))}</li>`).join('')}</ul>`:''}
 ${nativeDecisions(story)}<button class="button button-light" data-action="check-native-packet" data-story="${esc(story.id)}">Check native import requirements</button><p data-native-import-result role="status" class="small">${prep?.nativeImportCheck?.accepted?'Eligible for the disposable development proof; production import remains disabled.':'Native import is blocked; resolve the recorded review requirements.'}</p>
 <a class="button button-dark" href="/api/stories/${encodeURIComponent(story.id)}/production-packet" download>Download production review packet ↗</a><p class="small muted">A structured review package with exact IDs, caption, ordered media and blockers. It cannot create a production record, clear rights or send a Buffer post.</p></section>`;
}

function storyPublishing(state, story) {
  const p = story.publishing || {};
  return `<div class="workspace-main">${sectionHeading('Before publishing', 'Review sources, permissions and existing draft activity before a handoff.')}<div data-production-visibility>${productionVisibility(story)}</div><div class="publishing-summary"><div><small>Provider observation</small><strong>${esc(human(p.observed || 'unknown'))}</strong></div><div><small>Manual lifecycle</small><strong>${esc(human(p.manualStatus || 'active'))}</strong></div><div><small>Instagram verification</small><strong>${p.instagramVerified ? 'Recorded' : 'Not independently verified'}</strong></div></div>
    ${p.multipleHandoffs || p.requiresReview ? '<div class="notice warning"><strong>Reconcile before another handoff.</strong><p>Existing provider activity or incomplete evidence needs review. A repeated send must not create a replacement draft.</p></div>' : ''}<section class="editorial-panel"><h2>Existing provider references</h2>${p.postIds?.length ? `<ul class="reference-list">${p.postIds.map(id => `<li><code>${esc(id)}</code><span>Buffer post reference</span></li>`).join('')}</ul>` : '<p class="muted">No mapped Buffer post IDs were supplied for this story. A missing mapping does not establish that no post exists.</p>'}${(p.reportedInstagramLinks || []).map(link => `<p>${external(link.url, 'Open provider-reported Instagram link')}</p>`).join('')}<p class="small muted">Provider links are reported evidence. They are not a fresh Instagram availability check.</p></section><section class="editorial-panel"><h2>Your working copy</h2><p>Download the caption, image order, notes and music direction for review. Sending this to production remains a separate approved step.</p>${proposalControl(story, 'Download proposal ↗', 'button button-dark')}${external('https://rickywelch.app.n8n.cloud/webhook/founder-command-center', 'Open existing Founder Studio', 'text-link inline-gap')}</section></div><aside class="workspace-aside"><section class="aside-block"><p class="eyebrow">Handoff boundary</p><h3>Production sends stay in n8n.</h3><p>This workspace does not create Buffer drafts, schedule, publish, delete, grant rights or change production workflows.</p><p>Review the actual existing draft and per-image permissions in the current production flow.</p></section><section class="aside-block"><h3>Outstanding preparation</h3>${blockers(story)}</section></aside>`;
}

export function library(state) {
  const query = (state.librarySearch || '').toLowerCase();
  const all = allStories(state).flatMap(story => (story.media || []).map(asset => ({ story, asset })));
  const candidates = all.filter(({ story, asset }) => matchesEditorialReview(asset,state.imageEditorialFilter||'all') && (!query || `${asset.title} ${asset.creator} ${asset.provider} ${story.title}`.toLowerCase().includes(query)) && (state.libraryRights === 'all' || (state.libraryRights === 'cleared' ? asset.rightsStatus === 'cleared' : asset.rightsStatus !== 'cleared')));
  return `${pageHeader('The archival image library', 'Photographs, with a history.', 'Review the existing publication’s image candidates, sources and recorded permissions.')}<div class="library-tools"><label class="search-field"><span aria-hidden="true">⌕</span><input type="search" id="library-search" placeholder="Search photographs, creators or stories" value="${esc(state.librarySearch)}" aria-label="Search image library"></label><label class="select-field">Rights view<select id="library-rights"><option value="all" ${state.libraryRights === 'all' ? 'selected' : ''}>All candidates</option><option value="pending" ${state.libraryRights === 'pending' ? 'selected' : ''}>Rights pending</option><option value="cleared" ${state.libraryRights === 'cleared' ? 'selected' : ''}>Clearance recorded</option></select></label>${editorialReviewFilter(state.imageEditorialFilter||'all')}<span class="small muted">${candidates.length} candidates</span></div><div class="asset-grid library-grid">${candidates.length ? candidates.map(({ story, asset }) => assetCard(story, asset, effective(story).selectedAssetIds.includes(asset.id), state.compared.some(c => c.storyId === story.id && c.assetId === asset.id))).join('') : empty('No matching photographs', 'Change the search, rights or editorial view. No image clearance is inferred from its source.')}</div>
    <section class="archive-directory">${sectionHeading('Start with the original archive', 'The existing curated directory supports discovery. Each image still needs its own rights review.')}<div class="source-grid">${(state.workspace.imageArchives || []).map(source => `<article class="source-card"><h3>${external(source.url, source.name)}</h3><p>${esc(source.rightsHint || 'Inspect the original image record for rights and reproduction terms.')}</p>${source.searchDomain ? `<small>${esc(source.searchDomain)}</small>` : ''}</article>`).join('') || empty('No archive directory returned', 'Existing source collections will appear when available.')}</div></section>`;
}

export function publishing(state) {
  const stories = filtered(allStories(state), state.search);
  const relevant = stories.filter(s => s.publishing?.postIds?.length || s.publishing?.requiresReview || s.localDraft);
  const mapped = new Set(allStories(state).flatMap(story => story.publishing?.postIds || []));
  const unmapped = (state.workspace.publishingPosts || []).filter(post => !mapped.has(post.id));
  return `${pageHeader('Before publishing', 'Production', 'Finish the checks and review existing publishing activity.')}<div class="notice subtle"><strong>Review here. Publish through the approved workflow.</strong><p>Editorial decisions, image rights and permission to publish are separate. Scheduling and sending remain in the existing publishing system.</p></div><div class="publishing-list">${relevant.length ? relevant.map(story => { const p = story.publishing || {}; const s = stateLabel(story); return `<article class="publishing-row"><a class="publishing-thumb" href="${storyUrl(story.id, 'publishing')}">${image(mediaFor(story)[0] || story.media?.[0])}</a><div><p class="eyebrow">${esc(story.id)}</p><h2><a href="${storyUrl(story.id, 'publishing')}">${esc(story.title)}</a></h2><div class="publishing-facts">${badge(s.label, s.tone)}${p.multipleHandoffs ? badge('Multiple handoffs', 'warn') : ''}<span>${p.postIds?.length || 0} mapped provider IDs</span></div><p>${p.instagramVerified ? 'Independent Instagram evidence recorded.' : 'Instagram outcome has not been independently verified.'}</p></div><a class="row-action" href="${storyUrl(story.id, 'publishing')}">Check this story →</a></article>`; }).join('') : empty('No handoffs in this view', 'No mapped provider records or local proposals match the current search.')}</div>${unmapped.length ? `<section class="editorial-panel unmapped-records">${sectionHeading('Provider records without a story mapping', 'These real Buffer records are not assigned to an existing story by the source ledger. Captions alone cannot establish a safe match.')}<div class="unmapped-list">${unmapped.map(post => `<article><div><code>${esc(post.id)}</code><div class="publishing-facts">${badge(human(post.status), 'warn')}${post.internalTest?badge('Internal test · never publish','warn'):''}<span>${post.imageCount ?? '—'} images</span><span>${post.sentAt ? esc(date(post.sentAt)) + ' ET' : 'No sent timestamp'}</span></div></div><p class="small muted">Instagram is not independently verified.</p>${post.externalLink ? external(post.externalLink, 'Provider-reported link') : '<span class="small muted">No external link reported</span>'}</article>`).join('')}</div></section>` : ''}${(state.workspace.intelligence?.duplicates || []).length ? `<section class="editorial-panel">${sectionHeading('Possible repeated story angles', 'Text similarity is a review signal, not proof of duplicate publication.')}<p class="muted">${state.workspace.intelligence.duplicates.length} candidate groups were reported by editorial comparison. Inspect the existing records before creating more stories.</p></section>` : ''}`;
}

export function archive(state) {
  const stories = filtered(allStories(state), state.search).filter(s => ['buffer_sent', 'instagram_posted_verified'].includes(s.publishing?.observed) || s.publishing?.manualStatus === 'posted');
  const verified = stories.filter(s => s.publishing?.instagramVerified);
  return `${pageHeader('The published archive', 'The publication, remembered.', 'Search completed work while retaining the distinction between a manual label, Buffer reporting and Instagram verification.')}<div class="archive-summary"><span><strong>${stories.length}</strong> reported or marked posted stories</span><span><strong>${verified.length}</strong> independently verified Instagram outcomes</span></div><div class="story-grid">${stories.length ? stories.map(story => storyCard(story)).join('') : empty('No published history in this view', 'Try another search. Stories are included only when marked posted or reported sent; no outcomes are fabricated.')}</div>`;
}

function measurementLabel(measurement = {}) {
  if (measurement.oldestAt && measurement.newestAt && measurement.oldestAt !== measurement.newestAt) return `${date(measurement.oldestAt)} – ${date(measurement.newestAt)} ET`;
  if (measurement.newestAt || measurement.oldestAt) return `${date(measurement.newestAt || measurement.oldestAt)} ET`;
  return 'measurement time not supplied';
}

export function analytics(state) {
  const analytics = state.workspace.analytics || {};
  const coverage = analytics.coverage || {};
  const publishing = analytics.publishing || {};
  const allMetrics = analytics.metrics || [];
  const metrics = allMetrics.filter(m=>m.available!==false&&(m.value??m.total)!==null&&(m.value??m.total)!==undefined);
  const bottlenecks = analytics.bottlenecks || [];
  const history = publishing.history || [];
  const max = Math.max(1, ...history.map(day => Number(day.count) || 0));
  const range = analytics.measurementRange || {};
  return `${pageHeader('Publication insights', 'Insights', 'What the available observations can tell us.')}<details class="notice subtle metric-measurement-note"><summary>Measurement details</summary><strong>Snapshot fetched: ${esc(date(analytics.observedAt || state.workspace.source?.bufferObservedAt))} ET</strong><p>Metric measurements: ${esc(measurementLabel(range))}. Fetching the source does not mean its metric values were measured again.</p><p>Measurement timestamps recorded: ${range.knownObservationCount ?? 'not supplied'} · without timestamps: ${range.unknownObservationCount ?? 'not supplied'}. Historical inspiration-account comparisons are not included in these publication metrics.</p></details><div class="stats-row"><div><strong>${coverage.posts ?? '—'}</strong><span>Observed Buffer records</span></div><div><strong>${coverage.sentPosts ?? publishing.sentCount ?? '—'}</strong><span>Reported sent</span></div><div><strong>${coverage.postsWithMetrics ?? '—'}</strong><span>Posts with metrics</span></div><div><strong>${publishing.activeDays ?? '—'}</strong><span>Days with reported sends</span></div></div>
    <section>${sectionHeading('Audience performance', 'Coverage and sample sizes are shown before any interpretation.')}<div class="metric-grid">${metrics.length ? metrics.map(metric => `<article class="metric-card"><p class="eyebrow">${esc(metric.label || human(metric.name))}</p><strong>${metric.available === false || (metric.value ?? metric.total) === null || (metric.value ?? metric.total) === undefined ? 'Not available' : esc(metric.value ?? metric.total)}</strong><p>${esc(metric.unit || '')}</p><small>${metric.sampleSize ?? 0} observations · ${esc(aggregationLabel(metric.aggregation))}</small><small class="metric-as-of">Measured: ${esc(measurementLabel(metric.measurement))}${metric.measurement?.unknownCount !== undefined ? ` · ${metric.measurement.unknownCount} timestamp${metric.measurement.unknownCount === 1 ? '' : 's'} unknown` : ''}</small></article>`).join('') : empty('Audience insights are not available yet', 'No audience measurements were supplied. Missing data is not zero; send counts do not establish reach or engagement.')}</div></section>
    <div class="two-column"><section class="paper-panel">${sectionHeading('Publishing rhythm', 'Counts are Buffer-reported sends, not verified Instagram reach.')}<div class="history-bars">${history.length ? history.slice(-14).map(day => `<div class="history-row"><span>${esc(day.date)}</span><progress max="${max}" value="${Number(day.count) || 0}" aria-label="${esc(day.date)}: ${Number(day.count) || 0} sends"></progress><strong>${Number(day.count) || 0}</strong></div>`).join('') : '<p class="muted">No dated send history is available.</p>'}</div></section><section class="paper-panel">${sectionHeading('Where work is waiting', 'Resolve the decision, rather than adding another automation.')}<ul class="bottleneck-list">${bottlenecks.length ? bottlenecks.map(item => `<li><div><strong>${esc(item.name || human(item.code))}</strong><small>${esc(item.description || 'Existing records needing review')}</small></div><span>${item.count}</span></li>`).join('') : '<li>No bottleneck summary was supplied.</li>'}</ul></section></div><section class="notice subtle"><strong>Interpretation has limits.</strong><ul>${(analytics.limitations?.length ? analytics.limitations : ['Provider status does not prove a live Instagram outcome.', 'Missing metrics are not zero, and correlations are not causal findings.']).map(limit => `<li>${esc(typeof limit === 'string' ? limit : limit.message)}</li>`).join('')}</ul></section>`;
}

export function compareDialog(state) {
  return `<div class="dialog-heading"><div><p class="eyebrow">Image review</p><h2>Compare the evidence.</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close image comparison">×</button></div><p class="muted">Compare previews and provenance. No visual or rights analysis is inferred.</p><div class="comparison-grid">${state.compared.map(({ storyId, assetId }) => { const story = allStories(state).find(s => s.id === storyId); const asset = story?.media?.find(m => m.id === assetId); return asset ? `<article>${image(asset)}<h3>${esc(asset.title)}</h3><p>${esc(asset.creator || 'Creator unrecorded')}</p>${badge(asset.rightsStatus === 'cleared' ? 'Clearance recorded' : 'Rights pending', asset.rightsStatus === 'cleared' ? 'good' : 'warn')}<p>${external(asset.sourceUrl, 'Original source')}</p><p class="small">${esc(asset.license || 'License not recorded')}</p><a class="text-link" href="${storyUrl(story.id, 'images')}" data-action="close-dialog">Open story →</a></article>` : ''; }).join('')}</div>`;
}

export function assetDialog(story, asset) {
  return `<div class="dialog-heading"><div><p class="eyebrow">Original image record</p><h2>${esc(asset.title || 'Untitled archival image')}</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close image details">×</button></div><div class="asset-detail"><div>${image(asset)}<p class="small muted">Preview only. Authenticity and publication rights require human review.</p><p class="small muted">${asset.localPreview ? `${asset.localPreview.sourceInspection?'Recorded source cached privately':'Private local preview'} · ${esc(asset.localPreview.width)} × ${esc(asset.localPreview.height)}. Identity and rights remain unverified.` : 'External preview loads directly in your browser. Availability may differ by network; a failed preview does not mean the source image is missing.'}</p>
<form data-preview-upload data-story="${esc(story.id)}" data-asset="${esc(asset.id)}">
<label class="field">Private preview file<input type="file" name="preview" accept="image/jpeg,image/png,image/webp" required></label>
<label class="small"><input type="checkbox" name="declaration" required> I confirm this is private review only; this file does not establish source identity or publication rights.</label>
<p class="small muted">JPG, PNG or WebP, up to 25 MiB. The original is preserved privately. Production records remain unchanged.</p>
<button type="submit" class="small-button">Save private preview</button><p data-upload-status role="status" class="small"></p></form></div><div><dl class="provenance-list"><div><dt>Creator</dt><dd>${esc(asset.creator || 'Not recorded')}</dd></div><div><dt>Source</dt><dd>${external(asset.sourceUrl, 'Open original source')}</dd></div><div><dt>Provider</dt><dd>${esc(asset.provider || 'Not recorded')}</dd></div><div><dt>Recorded license</dt><dd>${esc(asset.license || 'Not recorded')}</dd></div><div><dt>Rights status</dt><dd>${badge(human(asset.rightsStatus), asset.rightsStatus === 'cleared' ? 'good' : 'warn')}</dd></div><div><dt>Inspection evidence</dt><dd>${esc(human(asset.inspection?.access||'reference_uninspected'))} · ${esc(human(asset.inspection?.relevance||'relevance_unreviewed'))}. No automated aesthetic judgment.</dd></div><div><dt>Dimensions</dt><dd>${asset.width && asset.height ? `${esc(asset.width)} × ${esc(asset.height)}` : 'Not recorded'}</dd></div><div><dt>Existing asset ID</dt><dd><code>${esc(asset.id)}</code></dd></div><div><dt>Story</dt><dd>${esc(story.title)}</dd></div></dl>${asset.sourceCaption?`<section class="source-caption"><h3>Caption recorded at the source</h3><p class="body-copy">${esc(asset.sourceCaption)}</p><p class="small">${esc(asset.sourceCredit||'Credit not recorded')}${asset.sourceYears?.length?' · '+asset.sourceYears.join(', '):''}</p><p class="small muted">${esc(human(asset.sourceRelation))}${asset.sourceCaptionBasis?' · '+esc(human(asset.sourceCaptionBasis)):''}${asset.materialType?' · '+esc(human(asset.materialType)):''}. Source metadata is not visual or rights verification.</p>${asset.creatorBasis==='copyright_holder_only'?'<p class="notice warning">Copyright holder recorded; the photographer is not established by that credit.</p>':asset.creatorBasis==='explicit_source_photo_credit'?'<p class="small muted">Photographer named in source metadata; attribution still needs review.</p>':''}${asset.sourceResearchLinks?.length?`<div class="source-trails"><h4>Follow the photographic trail</h4>${asset.sourceResearchLinks.map(link=>`<p>${external(link.url,(link.kind==='photographer'?'Photographer: ':'Series / project: ')+link.label)}</p>`).join('')}<p class="small muted">Links reported in this image’s caption. Destinations, full-series coverage and rights have not been verified.</p></div>`:''}${asset.captureCoverage?`<p class="small muted">Captured page scan: ${esc(asset.captureCoverage.retainedCount)} of ${esc(asset.captureCoverage.referenceCount)} image references retained${asset.captureCoverage.pageTruncated?' · page text scan was truncated':''}${asset.captureCoverage.imageTagsFound>asset.captureCoverage.imageTagsConsidered?' · image tag budget reached':''}. A bounded source scan is not complete-shoot coverage or visual inspection.</p>`:''}${asset.dateContext==='different_year_context'?'<p class="notice warning">This image is dated differently from the story context. Preserve its actual date.</p>':''}</section>`:''}<p class="small muted">An accessible image, archive listing or source license label does not itself complete this image’s publication clearance.</p><section class="image-research-continuation"><h3>Follow this photograph</h3><p class="small muted">Prepare research from this exact frame, its reported creator and original series. This saves a brief; no AI or source request runs.</p><div class="carousel-actions">${[['deepen','Investigate this photograph'],['alternatives','Find stronger alternatives']].map(([intent,label])=>`<button class="small-button" data-photo-continuation="${intent}" data-story="${esc(story.id)}" data-asset="${esc(asset.id)}" data-revision="${esc(story.revision)}" data-working="${story.localDraft?.version||0}" data-preview-hash="${esc(asset.localPreview?.sha256||'')}">${label}</button>`).join('')}</div></section><section class="image-editorial-review"><h3>Your editorial judgment</h3><p class="small muted">Your judgment of this frame, or a problem to investigate. It does not change slides, verify a claim or grant image rights.</p>${asset.localReview?.decision==='reject'&&effective(story).selectedAssetIds.includes(asset.id)?'<p class="notice warning">This rejected image is still in the carousel. Review the sequence explicitly before production.</p>':''}
<form data-image-review data-story="${esc(story.id)}" data-asset="${esc(asset.id)}" data-version="${asset.localReview?.version||0}" data-revision="${esc(story.revision)}" data-working="${story.localDraft?.version||0}" data-preview-hash="${esc(asset.localPreview?.sha256||'')}"><label class="field">Editorial decision<select aria-label="Editorial decision" name="decision"><option value="hold" ${asset.localReview?.decision==='hold'?'selected':''}>Hold for review</option><option value="shortlist" ${asset.localReview?.decision==='shortlist'?'selected':''}>Shortlist</option><option value="reject" ${asset.localReview?.decision==='reject'?'selected':''}>Reject for this story</option></select></label><label class="field">What is this feedback about?<select name="basis" aria-label="Feedback type">${[['editorial_taste','Overall impression'],['photographic_style','Photographic style'],['composition','Composition or framing'],['mood','Mood'],['story_potential','Connection to this story'],['factual_issue','Possible factual error'],['source_issue','Credit or source question'],['rights_issue','Permission question'],['retrieval_issue','Preview will not load'],['interface_issue','Studio problem']].map(([key,label])=>`<option value="${key}" ${key===(asset.localReview?.context?.decisionBasis||'editorial_taste')?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Why this image?<textarea aria-label="Why this image?" name="reason" minlength="8" maxlength="1500" required>${esc(asset.localReview?.reason||'')}</textarea></label><button type="submit" class="small-button">Save editorial review</button><p data-review-status role="status" class="small"></p></form>
${asset.localReview?.context&&(asset.localReview.context.previewSha256||null)!==(asset.localPreview?.sha256||null)?'<p class="notice warning">This decision refers to an earlier preview. Review the replacement separately.</p>':''}${asset.localReview?`<details><summary>Editorial review history (${asset.localReview.version} versions)</summary><ul>${asset.localReview.history.map(r=>`<li>Version ${r.version}: ${esc(human(r.decision))}${r.basis?' · '+esc(human(r.basis)):''} — ${esc(r.reason)}</li>`).join('')}</ul><p class="small muted">Showing up to 50 latest decisions; earlier events remain in the private database.</p></details>`:''}</section></div></div>`;
}

export function staleDraftDialog(story) {
  const draft = effective(story);
  const known = new Set((story.media || []).map(asset => asset.id));
  const missing = draft.selectedAssetIds.filter(id => !known.has(id));
  const missingRoles = (draft.creativeBrief?.sequenceRoles || []).filter(item => !known.has(item.assetId));
  return `<div class="dialog-heading"><div><p class="eyebrow">Local draft recovery</p><h2>Review what changed.</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close draft comparison">×</button></div><p class="muted small">The source revision changed after this local draft was saved. Both copies remain available. Keeping local edits creates a new local revision; it does not update n8n.</p><div class="draft-comparison"><section><p class="eyebrow">Current source caption</p><h3>Package v${story.packageVersion || '—'}</h3><p><strong>${esc(story.title)}</strong> · ${esc(human(story.format))} · target ${esc(story.targetSlideCount)}</p><p class="body-copy">${esc(story.caption || 'No source caption recorded.')}</p><p class="small muted">${(story.selectedAssetIds || []).length} selected source images</p></section><section><p class="eyebrow">Your local caption</p><h3>Local version ${story.localDraft?.version || '—'}</h3><p><strong>${esc(draft.title)}</strong> · ${esc(human(draft.format))} · target ${esc(draft.targetSlideCount)}</p><p class="body-copy">${esc(draft.caption || 'No local caption recorded.')}</p><p class="small muted">${esc(draft.title || story.title)} · ${esc(human(draft.format || story.format))}${draft.targetSlideCount ? ` · target ${draft.targetSlideCount}` : ''}</p><p class="small muted">${draft.selectedAssetIds.length} locally selected images · ${esc(date(story.localDraft?.updatedAt))} ET</p>${draft.notes ? `<details><summary>Local notes</summary><p class="body-copy">${esc(draft.notes)}</p></details>` : ''}${draft.creativeBrief ? `<details><summary>Local creative direction</summary>${creativeBriefSummary(draft.creativeBrief)}</details>` : ''}</section></div>${missing.length ? `<div class="notice warning"><strong>${missing.length} selected image${missing.length === 1 ? ' is' : 's are'} no longer available in the current source.</strong><p>The original local version will remain in history. Keeping this proposal requires explicitly removing the unavailable image references from the new version.</p><ul>${missing.map(id => `<li><code>${esc(id)}</code></li>`).join('')}</ul></div>` : '<p class="small muted">Every locally selected asset is still present in the current source collection.</p>'}${missingRoles.length ? `<div class="notice warning"><strong>${missingRoles.length} narrative-role annotation${missingRoles.length === 1 ? ' refers' : 's refer'} to an unavailable source image.</strong><p>Keeping this draft also requires explicitly removing those unavailable annotations from the new version. The earlier creative brief remains in history.</p></div>` : ''}<div class="dialog-actions"><button class="button button-dark" data-action="rebase-draft" data-story="${esc(story.id)}">${missing.length || missingRoles.length ? `Keep local edits and review ${missing.length + missingRoles.length} unavailable reference${missing.length + missingRoles.length === 1 ? '' : 's'}` : 'Keep local edits after review'}</button><a class="button button-light" href="/api/stories/${encodeURIComponent(story.id)}/proposal" download>Download proposal before deciding ↗</a></div><p class="small muted">Earlier local versions are retained. No automatic merge or production write occurs.</p>`;
}

export function draftHistoryDialog(story, versions) {
  return `<div class="dialog-heading"><div><p class="eyebrow">Private editorial revisions</p><h2>Local version history.</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close local version history">×</button></div><p class="small muted">These are this development workspace’s local saves, not n8n workflow history or production revisions. Restoring creates another local save and preserves the versions below.</p>${versions.length ? `<div class="draft-history">${versions.map((draft, index) => `<details ${index === 0 ? 'open' : ''}><summary><strong>Version ${esc(draft.version)}</strong><span>${esc(date(draft.updatedAt))} ET · ${esc(human(draft.event || 'local save'))}</span></summary><p class="body-copy">${esc(draft.caption || 'No local caption recorded.')}</p><p class="small muted">${esc(draft.title || story.title)} · ${esc(human(draft.format || story.format))}${draft.targetSlideCount ? ` · target ${draft.targetSlideCount}` : ''}</p><p class="small muted">${draft.selectedAssetIds?.length || 0} selected images${draft.musicSelection?.track ? ` · ${esc(draft.musicSelection.track)} / ${esc(draft.musicSelection.artist)}` : ''}</p>${draft.notes ? `<details><summary>Editor’s notes</summary><p class="body-copy">${esc(draft.notes)}</p></details>` : ''}${draft.creativeBrief ? `<details><summary>Creative direction</summary>${creativeBriefSummary(draft.creativeBrief)}</details>` : ''}<button class="small-button" data-action="restore-local-version" data-story="${esc(story.id)}" data-index="${index}" ${fieldDisabled(story)}>Use this version as a new local draft</button></details>`).join('')}</div>` : empty('No local versions saved yet', 'Caption, sequence, notes and music edits will create private versions here. Existing production records remain untouched.')} ${story.localDraft?.stale ? '<div class="notice warning"><strong>Source revision changed.</strong><p>Compare and resolve the stale source before restoring a prior version.</p></div>' : ''}`;
}


export {discovery} from './discover.js';

export function carouselRehearsal(story, index = 0, fit = 'frame') {
  const assets = mediaFor(story); const position = Math.max(0, Math.min(assets.length - 1, index));
  const asset = assets[position]; if (!asset) return empty('No slides selected', 'Choose photographs in the existing image library.');
  const draft = effective(story); const role = draft.creativeBrief?.sequenceRoles?.find(r=>r.assetId===asset.id);
  return `<section class="carousel-rehearsal" data-rehearsal data-fit="${fit==='original'?'original':'frame'}"><div class="dialog-heading"><div><p class="eyebrow">Private carousel rehearsal · ${position+1} / ${assets.length}</p><h2>${esc(draft.title)}</h2></div><button class="icon-button" data-action="close-dialog" aria-label="Close carousel rehearsal">×</button></div>
  <div class="rehearsal-controls"><button class="small-button" data-action="rehearse-step" data-step="-1" ${position===0?'disabled':''} aria-label="Previous carousel image">← Previous</button><span role="status" aria-live="polite">Slide ${position+1} of ${assets.length}</span><button class="small-button" data-action="rehearse-step" data-step="1" ${position===assets.length-1?'disabled':''} aria-label="Next carousel image">Next →</button><label class="small">Framing<select data-rehearsal-fit aria-label="Framing"><option value="frame" ${fit==='original'?'':'selected'}>4:5 frame · contain</option><option value="original" ${fit==='original'?'selected':''}>Full image proportions</option></select></label></div>
  <div class="rehearsal-layout"><div class="rehearsal-stage">${image(asset,{eager:true})}</div><aside><p class="eyebrow">${position===0?'Opening photograph':`Slide ${position+1}`}</p><h3>${esc(asset.title)}</h3><p>${esc(asset.creator||'Creator not recorded')}</p>${badge(asset.rightsStatus==='cleared'?'Clearance recorded':'Rights pending',asset.rightsStatus==='cleared'?'good':'warn')}<p>${external(asset.sourceUrl,'Original source')}</p><p class="small">${asset.localPreview?`Private derivative: ${esc(asset.localPreview.width)} × ${esc(asset.localPreview.height)}; identity unverified.`:asset.width&&asset.height?`Recorded dimensions: ${esc(asset.width)} × ${esc(asset.height)}; not decoded original verification.`:'Original dimensions not recorded.'}</p><h3>Narrative purpose</h3><p>${role?esc(human(role.role)):'No narrative role assigned yet.'}</p>${role?.note?`<p>${esc(role.note)}</p>`:''}<p class="small muted">Arrow keys move between images. These framing modes are previews only: no crop, source image or export is changed. Private previews do not prove production readiness.</p></aside></div>
  <details class="rehearsal-caption"><summary>Read the current caption and music direction</summary><p class="body-copy">${esc(draft.caption||'No caption saved.')}</p><p>${draft.musicSelection?esc(`${draft.musicSelection.track} / ${draft.musicSelection.artist}`):'Music direction not selected.'}</p></details></section>`;
}
